insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('CA', 'default', 'Canadian reference chart of accounts', '{"fr":"Plan comptable de référence canadien"}'::jsonb, true, 'companies', array['CA-ASPE-BS', 'CA-ASPE-IS']::text[], null, 'There is no legal chart of accounts in Canada and no statute prescribes one for a company of any size. What is prescribed is the standard the statements are prepared to: section 71 of the Canada Business Corporations Regulations, 2001 requires the annual financial statements of a corporation to be prepared in accordance with Canadian GAAP, and section 70 defines that as the CPA Canada Handbook – Accounting, whose Part II holds the accounting standards for private enterprises. This chart is original. It follows the four-digit, five-block convention Canadian bookkeeping software shares — 1000 assets, 2000 liabilities, 3000 equity, 4000 revenue, 5000 and above expenses — and every block of codes is cut so that it reaches exactly one line of the two ASPE statements this pack carries. The labels are English because there is no official Canadian chart in either official language to transcribe; the French of a Québec set of books is in i18n/fr.json.', 'cbca-regs')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

