insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CA', 'CA-AB-P-5', 'Purchase in Alberta — GST 5 % recoverable', '{"fr":"Achat en Alberta — TPS de 5 % récupérable"}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Alberta is not a participating province and levies no general sales tax of its own, so a supplier there charges 5 % and nothing else. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. ', null, null, 250, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-AB', null),
  ('CA', 'CA-AB-S-5', 'Sale in Alberta — GST 5 %', '{"fr":"Vente en Alberta — TPS de 5 %"}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Alberta is not a participating province and levies no general sales tax of its own, so 5 % is the whole of the tax on a supply made there and the Canada Revenue Agency publishes it as such. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. One `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 60, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-AB', null),
  ('CA', 'CA-BC-P-12', 'Purchase in British Columbia — GST 5 % and provincial sales tax (PST), 12 % in all', '{"fr":"Achat en Colombie-Britannique — TPS de 5 % et TVP, 12 % en tout"}'::jsonb, 'The federal part recoverable, the provincial part a cost on the line it taxes', 'percent', 12, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Section 37 of the Provincial Sales Tax Act (SBC 2012, c. 35) makes a purchaser of tangible personal property liable for tax, and subsection 34(1) of the same Act sets that tax at 7 % of the purchase price; the Province states the general rate as “7 % on the purchase or lease price of goods and services, with some exceptions”. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The provincial tax is **not** recoverable: neither the Excise Tax Act nor the provincial statute gives a purchaser a credit for it, which is the whole difference between a retail sales tax and a value added tax. So the code splits: 41.667 % of the tax — the federal 5 points — is a `tax` posting to the GST/HST recoverable account and to line 106 of form GST34, and 58.333 % is a `tax_on_base` posting, which carries no account of its own and lands on the accounts of the lines it taxes. A machine bought for $10,000 is capitalised at $10,700.', null, null, 300, 'gst', true, '{}'::tax_condition[], 'CA-BC', false, false, null, 'bc-psta', null, null, 'CA-BC', null),
  ('CA', 'CA-BC-S-12', 'Sale in British Columbia — GST 5 % and provincial sales tax (PST), 12 % in all', '{"fr":"Vente en Colombie-Britannique — TPS de 5 % et TVP, 12 % en tout"}'::jsonb, 'The federal and the provincial tax on one line, split at the posting', 'percent', 12, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Section 37 of the Provincial Sales Tax Act (SBC 2012, c. 35) makes a purchaser of tangible personal property liable for tax, and subsection 34(1) of the same Act sets that tax at 7 % of the purchase price; the Province states the general rate as “7 % on the purchase or lease price of goods and services, with some exceptions”. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. Two taxes, two administrations, and one code a bookkeeper picks: the rate stated here is the two added together, and the postings split it. The first `tax` posting is 41.667 % of the tax — the federal 5 points — and goes to the GST/HST charged account and to line 103 of form GST34; the second is 58.333 % — the provincial part — and goes to its own account and to no box of this form, because the provincial tax is not declared on the federal return. `box_factor` on the first posting is the same share as `factor`, so line 103 reports the federal part and not the whole.', 'S', null, 110, 'gst', true, '{}'::tax_condition[], 'CA-BC', false, false, null, 'bc-psta', null, null, 'CA-BC', null),
  ('CA', 'CA-MB-P-12', 'Purchase in Manitoba — GST 5 % and retail sales tax (RST), 12 % in all', '{"fr":"Achat au Manitoba — TPS de 5 % et TVD, 12 % en tout"}'::jsonb, 'The federal part recoverable, the provincial part a cost on the line it taxes', 'percent', 12, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Subsection 2(1) of The Retail Sales Tax Act (CCSM c. R130) makes every purchaser of tangible personal property or a taxable service pay tax equal to the fair value multiplied by the general sales tax rate, and the definition of “general sales tax rate” in subsection 1(1) sets that rate at 7 % for tax that becomes payable after 30 June 2019. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The provincial tax is **not** recoverable: neither the Excise Tax Act nor the provincial statute gives a purchaser a credit for it, which is the whole difference between a retail sales tax and a value added tax. So the code splits: 41.667 % of the tax — the federal 5 points — is a `tax` posting to the GST/HST recoverable account and to line 106 of form GST34, and 58.333 % is a `tax_on_base` posting, which carries no account of its own and lands on the accounts of the lines it taxes. A machine bought for $10,000 is capitalised at $10,700.', null, null, 320, 'gst', true, '{}'::tax_condition[], 'CA-MB', false, false, null, 'mb-rsta', null, null, 'CA-MB', null),
  ('CA', 'CA-MB-S-12', 'Sale in Manitoba — GST 5 % and retail sales tax (RST), 12 % in all', '{"fr":"Vente au Manitoba — TPS de 5 % et TVD, 12 % en tout"}'::jsonb, 'The federal and the provincial tax on one line, split at the posting', 'percent', 12, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Subsection 2(1) of The Retail Sales Tax Act (CCSM c. R130) makes every purchaser of tangible personal property or a taxable service pay tax equal to the fair value multiplied by the general sales tax rate, and the definition of “general sales tax rate” in subsection 1(1) sets that rate at 7 % for tax that becomes payable after 30 June 2019. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. Two taxes, two administrations, and one code a bookkeeper picks: the rate stated here is the two added together, and the postings split it. The first `tax` posting is 41.667 % of the tax — the federal 5 points — and goes to the GST/HST charged account and to line 103 of form GST34; the second is 58.333 % — the provincial part — and goes to its own account and to no box of this form, because the provincial tax is not declared on the federal return. `box_factor` on the first posting is the same share as `factor`, so line 103 reports the federal part and not the whole.', 'S', null, 130, 'gst', true, '{}'::tax_condition[], 'CA-MB', false, false, null, 'mb-rsta', null, null, 'CA-MB', null),
  ('CA', 'CA-NB-P-15', 'Purchase in New Brunswick — HST 15 % recoverable', '{"fr":"Achat au Nouveau-Brunswick — TVH de 15 % récupérable"}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. New Brunswick is a participating province and the harmonized sales tax a supplier charges there is 15 %. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The whole of the harmonized tax is recoverable, federal part and provincial part alike: subsection 169(1) makes no distinction between them.', null, null, 220, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NB', null),
  ('CA', 'CA-NB-S-15', 'Sale in New Brunswick — HST 15 %', '{"fr":"Vente au Nouveau-Brunswick — TVH de 15 %"}'::jsonb, 'The harmonized sales tax of a participating province: one rate, one administration, one box', 'percent', 15, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. New Brunswick is a participating province: the federal and the provincial parts are levied and administered together as the harmonized sales tax, 15 % in all, of which 5 points are the tax of subsection 165(1) and 10 points the tax of subsection 165(2). Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. The whole of the tax is collected for the Receiver General, so one `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 30, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NB', null),
  ('CA', 'CA-NL-P-15', 'Purchase in Newfoundland and Labrador — HST 15 % recoverable', '{"fr":"Achat à Terre-Neuve-et-Labrador — TVH de 15 % récupérable"}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Newfoundland and Labrador is a participating province and the harmonized sales tax a supplier charges there is 15 %. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The whole of the harmonized tax is recoverable, federal part and provincial part alike: subsection 169(1) makes no distinction between them.', null, null, 230, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NL', null),
  ('CA', 'CA-NL-S-15', 'Sale in Newfoundland and Labrador — HST 15 %', '{"fr":"Vente à Terre-Neuve-et-Labrador — TVH de 15 %"}'::jsonb, 'The harmonized sales tax of a participating province: one rate, one administration, one box', 'percent', 15, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Newfoundland and Labrador is a participating province: the federal and the provincial parts are levied and administered together as the harmonized sales tax, 15 % in all, of which 5 points are the tax of subsection 165(1) and 10 points the tax of subsection 165(2). Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. The whole of the tax is collected for the Receiver General, so one `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 40, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NL', null),
  ('CA', 'CA-NS-P-14', 'Purchase in Nova Scotia — HST 14 % recoverable', '{"fr":"Achat en Nouvelle-Écosse — TVH de 14 % récupérable"}'::jsonb, null, 'percent', 14, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Nova Scotia is a participating province and the harmonized sales tax a supplier charges there is 14 %. Nova Scotia''s provincial part fell from 10 points to 9 on 1 April 2025, which is why the rate here is 14 % and not 15 %. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The whole of the harmonized tax is recoverable, federal part and provincial part alike: subsection 169(1) makes no distinction between them.', null, null, 210, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-which-rate', null, null, 'CA-NS', null),
  ('CA', 'CA-NS-S-14', 'Sale in Nova Scotia — HST 14 %', '{"fr":"Vente en Nouvelle-Écosse — TVH de 14 %"}'::jsonb, 'The harmonized sales tax of a participating province: one rate, one administration, one box', 'percent', 14, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Nova Scotia is a participating province: the federal and the provincial parts are levied and administered together as the harmonized sales tax, 14 % in all, of which 5 points are the tax of subsection 165(1) and 9 points the tax of subsection 165(2). Nova Scotia''s provincial part fell from 10 points to 9 on 1 April 2025, which is why the rate here is 14 % and not the 15 % the three other Atlantic provinces charge; the Canada Revenue Agency states the change in as many words. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. The whole of the tax is collected for the Receiver General, so one `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 20, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-which-rate', null, null, 'CA-NS', null),
  ('CA', 'CA-NT-P-5', 'Purchase in Northwest Territories — GST 5 % recoverable', '{"fr":"Achat dans les Territoires du Nord-Ouest — TPS de 5 % récupérable"}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Northwest Territories is not a participating province and levies no general sales tax of its own, so a supplier there charges 5 % and nothing else. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. ', null, null, 260, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NT', null),
  ('CA', 'CA-NT-S-5', 'Sale in Northwest Territories — GST 5 %', '{"fr":"Vente dans les Territoires du Nord-Ouest — TPS de 5 %"}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Northwest Territories is not a participating province and levies no general sales tax of its own, so 5 % is the whole of the tax on a supply made there and the Canada Revenue Agency publishes it as such. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. One `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 70, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NT', null),
  ('CA', 'CA-NU-P-5', 'Purchase in Nunavut — GST 5 % recoverable', '{"fr":"Achat au Nunavut — TPS de 5 % récupérable"}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Nunavut is not a participating province and levies no general sales tax of its own, so a supplier there charges 5 % and nothing else. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. ', null, null, 270, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NU', null),
  ('CA', 'CA-NU-S-5', 'Sale in Nunavut — GST 5 %', '{"fr":"Vente au Nunavut — TPS de 5 %"}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Nunavut is not a participating province and levies no general sales tax of its own, so 5 % is the whole of the tax on a supply made there and the Canada Revenue Agency publishes it as such. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. One `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 80, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-NU', null),
  ('CA', 'CA-ON-P-13', 'Purchase in Ontario — HST 13 % recoverable', '{"fr":"Achat en Ontario — TVH de 13 % récupérable"}'::jsonb, null, 'percent', 13, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Ontario is a participating province and the harmonized sales tax a supplier charges there is 13 %. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The whole of the harmonized tax is recoverable, federal part and provincial part alike: subsection 169(1) makes no distinction between them.', null, null, 200, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-ON', null),
  ('CA', 'CA-ON-S-13', 'Sale in Ontario — HST 13 %', '{"fr":"Vente en Ontario — TVH de 13 %"}'::jsonb, 'The harmonized sales tax of a participating province: one rate, one administration, one box', 'percent', 13, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Ontario is a participating province: the federal and the provincial parts are levied and administered together as the harmonized sales tax, 13 % in all, of which 5 points are the tax of subsection 165(1) and 8 points the tax of subsection 165(2). Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. The whole of the tax is collected for the Receiver General, so one `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 10, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-ON', null),
  ('CA', 'CA-P-E', 'Exempt purchase', '{"fr":"Achat exonéré"}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2026-01-01', null, 'Excise Tax Act, Schedule V lists the exempt supplies — Part I real property, Part II health care, Part V.1 supplies by charities, Part VI supplies by public institutions, Part VII financial services. A supplier making one charges no tax, so the buyer has none to claim, and the purchase reaches no box of form GST34. No exemption reason code: the VATEX list belongs to the common system of VAT, which does not reach Canada, and the article is stated here instead.', 'E', null, 340, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-P-IMP-5', 'Import of goods — GST 5 % paid at the border', '{"fr":"Importation de biens — TPS de 5 % payée à la frontière"}'::jsonb, 'The tax is assessed on a customs document and not on the supplier''s invoice', 'percent', 5, 'purchase', 'import', date '2026-01-01', null, 'Excise Tax Act, section 212 imposes tax at the rate set out in subsection 165(1) on every person who is liable under the Customs Act to pay duty on imported goods, calculated on the value of the goods, and section 214 makes it payable and collected as if it were a customs duty. The supplier''s own invoice carries no Canadian tax: the tax is assessed on the accounting document the Canada Border Services Agency releases the goods against, which is why the two `tax` postings of this code net to nothing on the supplier''s account — one debits the input tax credit and carries it to line 106 under subsection 169(1), the other credits what is owed at the border. Only the provincial part of the HST is left out: section 212.1 charges it on goods imported by a resident of a participating province, and a commercial importer accounts for it on their return rather than at the border.', null, null, 360, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-P-O', 'Purchase outside the scope of the tax', '{"fr":"Achat hors du champ de la taxe"}'::jsonb, null, 'percent', 0, 'purchase', 'not_subject', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1) taxes a taxable supply made in Canada. Wages and salaries, dividends, interest on a loan the lender treats as a financial service, a payment to a person who is not required to be registered because their taxable supplies stay under the $30,000 small-supplier threshold of section 148, and a supply section 142 places outside Canada are all outside it, each for its own reason. This is the code for an outlay that carries no tax and gives rise to none, and it reaches no box.', 'O', null, 350, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-P-SA-5', 'Imported taxable supply — GST 5 % self-assessed', '{"fr":"Fourniture taxable importée — TPS de 5 % autocotisée"}'::jsonb, 'Nobody charged the tax, the recipient owes it, and it is a cost', 'percent', 5, 'purchase', 'foreign_services_received', date '2026-01-01', null, 'Excise Tax Act, section 218: every recipient of an imported taxable supply shall pay tax calculated at the rate set out in subsection 165(1) on the value of the consideration. Section 217 defines an imported taxable supply, and its first paragraph is the case this code is for — a taxable supply of a service or of intangible personal property made outside Canada to a person resident in Canada, otherwise than for consumption, use or supply exclusively in the course of commercial activities. Because the recipient is not using it in commercial activities, there is no input tax credit under subsection 169(1) at the other end: the tax is a cost, which the `tax_on_base` posting puts on the accounts of the lines it taxes, and the `tax` posting at −100 credits what is owed and carries it to line 405 of form GST34, “other GST/HST to be self-assessed”. A recipient who does use the service in commercial activities owes nothing under section 218 and books the purchase with CA-P-O.', null, null, 370, 'gst', false, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-P-Z', 'Zero-rated purchase', '{"fr":"Achat détaxé"}'::jsonb, null, 'percent', 0, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(3): the tax rate in respect of a taxable supply that is a zero-rated supply is 0 %. This is the buyer''s side of a purchase the supplier zero-rated — basic groceries under Schedule VI, Part III, prescription drugs under Part I, medical devices under Part II, freight transportation under Part VII. Nothing was charged and nothing is recovered, so the code carries a base posting and no tax posting, and reaches no box of form GST34.', 'Z', null, 330, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-PE-P-15', 'Purchase in Prince Edward Island — HST 15 % recoverable', '{"fr":"Achat à l''Île-du-Prince-Édouard — TVH de 15 % récupérable"}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Prince Edward Island is a participating province and the harmonized sales tax a supplier charges there is 15 %. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The whole of the harmonized tax is recoverable, federal part and provincial part alike: subsection 169(1) makes no distinction between them.', null, null, 240, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-PE', null),
  ('CA', 'CA-PE-S-15', 'Sale in Prince Edward Island — HST 15 %', '{"fr":"Vente à l''Île-du-Prince-Édouard — TVH de 15 %"}'::jsonb, 'The harmonized sales tax of a participating province: one rate, one administration, one box', 'percent', 15, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Prince Edward Island is a participating province: the federal and the provincial parts are levied and administered together as the harmonized sales tax, 15 % in all, of which 5 points are the tax of subsection 165(1) and 10 points the tax of subsection 165(2). Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. The whole of the tax is collected for the Receiver General, so one `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 50, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-PE', null),
  ('CA', 'CA-QC-P-14975', 'Purchase in Québec — GST 5 % and Québec sales tax (QST), 14.975 % in all', '{"fr":"Achat au Québec — TPS de 5 % et TVQ, 14,975 % en tout"}'::jsonb, 'Both taxes recoverable, each from its own administration', 'percent', 14.975, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Section 16 of the Act respecting the Québec sales tax imposes the Québec sales tax at 9.975 % on the value of the consideration for a taxable supply made in Québec, and 0 % where the supply is zero-rated. The QST is charged on the same consideration as the GST and not on the consideration plus the GST: neither tax is in the base of the other. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The Québec sales tax is recoverable on the same footing: section 199 of the Act respecting the Québec sales tax gives a registrant an input tax refund for the tax payable on property and services acquired in the course of its commercial activities. So the code has two `tax` postings and no cost: 33.389 % of the tax — the federal 5 points — to the GST/HST recoverable account and to line 106 of form GST34, and 66.611 % to the QST recoverable account and to no box, because the refund is claimed from Revenu Québec on form FPZ-500 and this pack carries the federal form.', null, null, 290, 'gst', true, '{}'::tax_condition[], 'CA-QC', false, false, null, 'ltvq', null, null, 'CA-QC', null),
  ('CA', 'CA-QC-S-14975', 'Sale in Québec — GST 5 % and Québec sales tax (QST), 14.975 % in all', '{"fr":"Vente au Québec — TPS de 5 % et TVQ, 14,975 % en tout"}'::jsonb, 'The federal and the provincial tax on one line, split at the posting', 'percent', 14.975, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Section 16 of the Act respecting the Québec sales tax imposes the Québec sales tax at 9.975 % on the value of the consideration for a taxable supply made in Québec, and 0 % where the supply is zero-rated. The QST is charged on the same consideration as the GST and not on the consideration plus the GST: neither tax is in the base of the other. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. Two taxes, two administrations, and one code a bookkeeper picks: the rate stated here is the two added together, and the postings split it. The first `tax` posting is 33.389 % of the tax — the federal 5 points — and goes to the GST/HST charged account and to line 103 of form GST34; the second is 66.611 % — the provincial part — and goes to its own account and to no box of this form, because the provincial tax is not declared on the federal return. `box_factor` on the first posting is the same share as `factor`, so line 103 reports the federal part and not the whole. Revenu Québec publishes both ways of working the pair out and says that a cash register calculating the GST and the QST in one step uses the single rate of 14.975 %, which is the rate this code carries. The QST is declared to Revenu Québec on form FPZ-500 and this pack carries one declaration form; the README says what that leaves out.', 'S', null, 100, 'gst', true, '{}'::tax_condition[], 'CA-QC', false, false, null, 'ltvq', null, null, 'CA-QC', null),
  ('CA', 'CA-S-E-FINANCIAL', 'Exempt sale — financial service', '{"fr":"Vente exonérée — service financier"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Excise Tax Act, Schedule V, Part VII, section 1 exempts a supply of a financial service that is not included in Part IX of Schedule VI, and section 2 exempts a supply deemed to be one by subsection 150(1). “Financial service” is defined in subsection 123(1) in fourteen paragraphs and taken back in nine. An exempt supply is not a taxable supply, so no tax is charged on it and — unlike a zero-rated supply — no input tax credit is available on what was bought to make it. No exemption reason code: the VATEX list of EN 16931 names articles of Directive 2006/112/EC and Canada is outside the common system of VAT, so the article this line is exempt under is stated here instead.', 'E', null, 170, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-S-E-RESIDENTIAL-RENT', 'Exempt sale — residential rent of at least one month', '{"fr":"Vente exonérée — loyer résidentiel d''au moins un mois"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Excise Tax Act, Schedule V, Part I, section 6 exempts a supply of a residential complex or of a residential unit in one, by way of lease, licence or similar arrangement, for occupancy as a place of residence or lodging by an individual, “where the period throughout which continuous occupancy of the complex or unit is given to the same individual under the arrangement is at least one month”; paragraph (b) exempts a residential unit let for no more than $20 a day of occupancy. The month and the kind of premises are facts about the arrangement and not figures in the books, which `supply_nature` records. A commercial lease is not in this section and is taxable. No exemption reason code, for the reason given on CA-S-E-FINANCIAL.', 'E', null, 180, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-S-O-OUTSIDE', 'Sale of a supply made outside Canada', '{"fr":"Vente d''une fourniture effectuée hors du Canada"}'::jsonb, null, 'percent', 0, 'sale', 'not_subject', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1) taxes a taxable supply “made in Canada” and nothing else, and section 142 is what decides where a supply is made: goods are supplied in Canada where they are, or are to be, delivered or made available in Canada, and a service is supplied in Canada where it is, or is to be, performed in whole or in part in Canada. A supply that section 142 places outside Canada is outside Division II altogether — it is not zero-rated and it is not exempt, and no tax of any rate applies to it. The revenue still reaches line 101, which asks for total sales and other revenue.', 'O', null, 190, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-S-Z-EXPORT', 'Zero-rated sale — goods exported by the recipient', '{"fr":"Vente détaxée — biens exportés par l''acquéreur"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Excise Tax Act, subsection 165(3): the tax rate in respect of a taxable supply that is a zero-rated supply is 0 %. Schedule VI, Part V, section 1 zero-rates a supply of tangible personal property made to a recipient other than a consumer who intends to export it, on five conditions the ledger cannot see: the recipient exports it as soon as is reasonable, does not acquire it for consumption, use or supply in Canada before exporting it, does not have it further processed in Canada, and the supplier “maintains evidence satisfactory to the Minister of the exportation of the property by the recipient”. `conditions` records that last one as `transport_evidence` and records no document: there is nowhere in the core to keep a proof of export, and the README says so. The supply is zero-rated and not exempt, so the seller keeps full input tax credits on what it cost to make. No exemption reason code: BT-121 comes from the VATEX list of EN 16931, whose codes name articles of Directive 2006/112/EC, and Canada is outside the common system of VAT.', 'G', null, 140, 'gst', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-S-Z-GROCERIES', 'Zero-rated sale — basic groceries', '{"fr":"Vente détaxée — produits alimentaires de base"}'::jsonb, null, 'percent', 0, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, Schedule VI, Part III, section 1 zero-rates supplies of food or beverages for human consumption, and excludes a long list the ledger cannot tell apart from the rest: alcoholic beverages, cannabis products, carbonated beverages, fruit-flavoured drinks under 25 % juice, candies and confectionery, chips and similar snack foods, salted nuts and seeds, granola and snack mixtures other than breakfast cereals, and ice lollies. What is supplied, classified more finely than any chart of accounts holds it, is exactly what `supply_nature` is for. Subsection 165(3) sets the rate at 0 %, and a zero-rated supply keeps the seller''s input tax credits.', 'Z', null, 160, 'gst', true, array['supply_nature']::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-S-Z-SERVICE-NR', 'Zero-rated sale — service supplied to a non-resident', '{"fr":"Vente détaxée — service fourni à un non-résident"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Excise Tax Act, Schedule VI, Part V, section 7 zero-rates a supply of a service made to a non-resident person, and then takes eight kinds of service back out of it: a service made to an individual who is in Canada when they have contact with the supplier about it, a service rendered to an individual while that individual is in Canada, an advisory, consulting or professional service, a postal service, a service in respect of real property situated in Canada, a service in respect of tangible personal property situated in Canada when the service is performed, a service of acting as agent, and a transportation or telecommunication service. Whether the customer is a non-resident is a fact about the party and not a figure in the books, which is what `buyer_status` records. Subsection 165(3) is what makes the rate 0 %.', 'G', null, 150, 'gst', true, array['buyer_status']::tax_condition[], null, false, false, null, 'eta', null, null, null, null),
  ('CA', 'CA-SK-P-11', 'Purchase in Saskatchewan — GST 5 % and provincial sales tax (PST), 11 % in all', '{"fr":"Achat en Saskatchewan — TPS de 5 % et TVP, 11 % en tout"}'::jsonb, 'The federal part recoverable, the provincial part a cost on the line it taxes', 'percent', 11, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Subsection 5(1) of The Provincial Sales Tax Act (RSS 1978, c. P-34.1) makes every consumer of tangible personal property purchased at a retail sale in Saskatchewan liable for a tax “computed at the rate of 6 % of the value of the property to be consumed”, and subsections 5(2) and 5(3) say the same of a user of property and of a taxable service. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. The provincial tax is **not** recoverable: neither the Excise Tax Act nor the provincial statute gives a purchaser a credit for it, which is the whole difference between a retail sales tax and a value added tax. So the code splits: 45.455 % of the tax — the federal 5 points — is a `tax` posting to the GST/HST recoverable account and to line 106 of form GST34, and 54.545 % is a `tax_on_base` posting, which carries no account of its own and lands on the accounts of the lines it taxes. A machine bought for $10,000 is capitalised at $10,700.', null, null, 310, 'gst', true, '{}'::tax_condition[], 'CA-SK', false, false, null, 'sk-psta', null, null, 'CA-SK', null),
  ('CA', 'CA-SK-S-11', 'Sale in Saskatchewan — GST 5 % and provincial sales tax (PST), 11 % in all', '{"fr":"Vente en Saskatchewan — TPS de 5 % et TVP, 11 % en tout"}'::jsonb, 'The federal and the provincial tax on one line, split at the posting', 'percent', 11, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Subsection 5(1) of The Provincial Sales Tax Act (RSS 1978, c. P-34.1) makes every consumer of tangible personal property purchased at a retail sale in Saskatchewan liable for a tax “computed at the rate of 6 % of the value of the property to be consumed”, and subsections 5(2) and 5(3) say the same of a user of property and of a taxable service. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. Two taxes, two administrations, and one code a bookkeeper picks: the rate stated here is the two added together, and the postings split it. The first `tax` posting is 45.455 % of the tax — the federal 5 points — and goes to the GST/HST charged account and to line 103 of form GST34; the second is 54.545 % — the provincial part — and goes to its own account and to no box of this form, because the provincial tax is not declared on the federal return. `box_factor` on the first posting is the same share as `factor`, so line 103 reports the federal part and not the whole.', 'S', null, 120, 'gst', true, '{}'::tax_condition[], 'CA-SK', false, false, null, 'sk-psta', null, null, 'CA-SK', null),
  ('CA', 'CA-YT-P-5', 'Purchase in Yukon — GST 5 % recoverable', '{"fr":"Achat au Yukon — TPS de 5 % récupérable"}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Yukon is not a participating province and levies no general sales tax of its own, so a supplier there charges 5 % and nothing else. Excise Tax Act, subsection 169(1): a registrant acquiring property or a service for consumption, use or supply in the course of a commercial activity has an input tax credit for the tax that becomes payable on it, and subsection 225(1) subtracts the credits claimed from the tax collected to give the net tax of the reporting period. The credit is claimed on line 106 of the return. The base of a purchase reaches no box: form GST34 has no input side other than the credit itself. ', null, null, 280, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-YT', null),
  ('CA', 'CA-YT-S-5', 'Sale in Yukon — GST 5 %', '{"fr":"Vente au Yukon — TPS de 5 %"}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Excise Tax Act, subsection 165(1): every recipient of a taxable supply made in Canada pays tax calculated at the rate of 5 % on the value of the consideration, and subsection 165(2) adds, on a supply made in a participating province, tax at the tax rate for that province — the definition of “tax rate” in subsection 123(1) taking the rate prescribed for the province where a sales tax harmonization agreement is in force. Yukon is not a participating province and levies no general sales tax of its own, so 5 % is the whole of the tax on a supply made there and the Canada Revenue Agency publishes it as such. Which province a supply is made in is decided by Schedule IX and by the New Harmonized Value-added Tax System Regulations, and never by where the invoice was addressed, which is what `applies_when.supply_in` records here. One `tax` posting carries it to the GST/HST charged account and to line 103 of form GST34.', 'S', null, 90, 'gst', true, '{}'::tax_condition[], null, false, false, null, 'cra-rates', null, null, 'CA-YT', null)
