on conflict (tax_template_id, document_kind, posting_type, sequence) do update set
  factor_percent     = excluded.factor_percent,
  account_code       = excluded.account_code,
  declaration_box    = excluded.declaration_box,
  declaration_boxes  = excluded.declaration_boxes,
  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CA', 'CA-GST34', 'Goods and Services Tax / Harmonized Sales Tax Return (GST34)', array['month', 'quarter', 'year']::declaration_period[], 'quarter'::declaration_period, date '2026-01-01', null, 'Excise Tax Act, subsection 238(1): every registrant shall file a return with the Minister for each reporting period. The reporting period is section 245: paragraph 245(2)(c) makes it “the fiscal quarter of the registrant” in all cases the two paragraphs before it do not catch, and those two are the exceptions — the fiscal month where the threshold amount exceeds $6,000,000 or the registrant has elected under section 246, and the fiscal year where an election under section 248 is in effect or the registrant is a charity or a listed financial institution. So the form is filed on three cadences and the statute still gives one of them to everybody who has asked for nothing, which is what `period_default` states. The Canada Revenue Agency describes the same thing administratively by turnover: annual under $1.5 million, quarterly between $1.5 and $6 million, monthly above. This form is the federal one and the only one the pack carries; a registrant in Québec files form FPZ-500 with Revenu Québec for the same period, and the README says what that leaves out here.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Excise Tax Act, paragraph 238(1)(b): a return is filed “within one month after the end of the reporting period of the registrant”, and paragraph 228(2)(b) makes the net tax remittable on or before the same day. That is the rule for a monthly and a quarterly filer, and the Canada Revenue Agency states it as “1 month after the end of the reporting period”. Two cases this rule does not produce, and neither is expressible as a second deadline on one form: an annual filer has three months under subparagraph 238(1)(a)(iii), six under subparagraph (i) if they are a listed financial institution, and an individual with business income and a 31 December year end files by 15 June under subparagraph (ii) while still remitting by 30 April under paragraph 228(2)(a). The README records that gap.', 'eta', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('CA', 'CA-GST34', '101', 'base', 'Total sales and other revenue', '{"fr":"Total des ventes et autres recettes"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 101: “Enter your total sales and other revenue. Do not include provincial sales tax, GST or HST. If you are using the quick method of accounting, include the GST or HST.” Every sale of this pack posts its base here, taxable, zero-rated, exempt or outside the scope of the tax alike, and nothing else does: form GST34 carries no input-side base. The printed box asks for whole dollars, and the pack files it in cents — the README says why.', 'gst34'),
  ('CA', 'CA-GST34', '103', 'tax', 'GST/HST collected or collectible', '{"fr":"TPS/TVH perçue ou percevable"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 103: “Enter the total of all GST and HST amounts that you collected or that became collectible by you in the reporting period.” It is element A(a) of the net tax formula of subsection 225(1) of the Excise Tax Act. Only the federal tax reaches it: on a Québec, British Columbia, Saskatchewan or Manitoba code the posting reports its own share through `box_factor`, and the provincial tax reaches no box of this form.', 'gst34'),
  ('CA', 'CA-GST34', '104', 'tax', 'Adjustments to be added to the net tax', '{"fr":"Redressements à ajouter à la taxe nette"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 104: “Enter the total amount of adjustments to be added to the net tax for the reporting period (for example, the GST/HST obtained from the recovery of a bad debt).” Element A(b) of subsection 225(1). No tax of this pack posts here: an adjustment is an entry somebody makes, not a rate on a line.', 'gst34'),
  ('CA', 'CA-GST34', '105', 'total', 'Total GST/HST and adjustments for period', '{"fr":"Total de la TPS/TVH et des redressements pour la période"}'::jsonb, 40, null, array['103', '104']::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 105: “Total GST/HST and adjustments for period (add lines 103 and 104)”.', 'gst34'),
  ('CA', 'CA-GST34', '106', 'tax', 'GST/HST paid or payable (input tax credits)', '{"fr":"TPS/TVH payée ou payable (crédits de taxe sur les intrants)"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 106: “Enter the GST/HST you paid or that is payable by you on qualifying expenses (input tax credits – ITCs) for the current period and any eligible unclaimed ITCs from a previous period.” The credit itself is subsection 169(1) of the Excise Tax Act and it is element B(a) of the net tax formula of subsection 225(1). The Québec input tax refund is not here: it is claimed from Revenu Québec on form FPZ-500.', 'gst34'),
  ('CA', 'CA-GST34', '107', 'tax', 'Adjustments to be deducted when determining the net tax', '{"fr":"Redressements à déduire pour le calcul de la taxe nette"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 107: “Enter the total amount of adjustments to be deducted when determining the net tax for the reporting period (for example, the GST/HST included in a bad debt).” Element B(b) of subsection 225(1). No tax of this pack posts here.', 'gst34'),
  ('CA', 'CA-GST34', '108', 'total', 'Total ITCs and adjustments', '{"fr":"Total des CTI et des redressements"}'::jsonb, 70, null, array['106', '107']::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 108: “Total ITCs and adjustments (add lines 106 and 107)”.', 'gst34'),
  ('CA', 'CA-GST34', '109', 'total', 'Net tax', '{"fr":"Taxe nette"}'::jsonb, 80, null, array['105']::text[], array['108']::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 109: “Net tax (subtract line 108 from line 105)”. It is the formula A − B of subsection 225(1) of the Excise Tax Act, written out on the form.', 'gst34'),
  ('CA', 'CA-GST34', '110', 'tax', 'Instalment and other annual filer payments', '{"fr":"Acomptes provisionnels et autres paiements de déclarants annuels"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 110: “Enter any instalment and other annual filer payments you made for the reporting period.” Section 237 of the Excise Tax Act is what makes an annual filer pay instalments. No tax of this pack posts here: an instalment is a payment, not a tax on a document.', 'gst34'),
  ('CA', 'CA-GST34', '111', 'tax', 'Rebates', '{"fr":"Remboursements"}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 111: “Enter the total amount of the GST/HST rebates, only if the rebate form indicates that you can claim the amount on this line.” The instructions add that the rebate application is generally filed with the return. No tax of this pack posts here.', 'gst34'),
  ('CA', 'CA-GST34', '112', 'total', 'Total other credits', '{"fr":"Total des autres crédits"}'::jsonb, 110, null, array['110', '111']::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 112: “Total other credits (add lines 110 and 111)”.', 'gst34'),
  ('CA', 'CA-GST34', '113A', 'total', 'Balance', '{"fr":"Solde"}'::jsonb, 120, null, array['109']::text[], array['112']::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 113 A: “Balance (subtract line 112 from line 109)”.', 'gst34'),
  ('CA', 'CA-GST34', '205', 'tax', 'GST/HST due on purchases of real property or of emission allowances', '{"fr":"TPS/TVH due sur l''achat d''immeubles ou de quotas d''émission"}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 205: “Enter the total amount of the GST/HST due on purchases of real property or purchases of emission allowances”, filled out only where the supplier was neither required nor deemed to have collected the tax — subsection 221(2) of the Excise Tax Act relieves the supplier of a taxable supply of real property to a registrant, and section 228(4) makes the recipient account for it. No tax of this pack posts here: Ekwo has no real-property purchase document, and the README says so.', 'gst34'),
  ('CA', 'CA-GST34', '405', 'tax', 'Other GST/HST to be self-assessed', '{"fr":"Autre TPS/TVH à autocotiser"}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 405: “Enter the total amount of other GST/HST to be self-assessed”, filled out “only if you have to self-assess GST/HST on an imported taxable supply or you have to self-assess the provincial part of HST”. Section 218 of the Excise Tax Act is the first of those and CA-P-SA-5 is the code that posts here.', 'gst34'),
  ('CA', 'CA-GST34', '113B', 'total', 'Total other debits', '{"fr":"Total des autres débits"}'::jsonb, 150, null, array['205', '405']::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 113 B: “Total other debits (add lines 205 and 405)”.', 'gst34'),
  ('CA', 'CA-GST34', '113C', 'total', 'Balance', '{"fr":"Solde"}'::jsonb, 160, null, array['113A', '113B']::text[], '{}'::text[], null, null, false, false, null, 'GST/HST Return Working Copy, line 113 C: “Balance (add lines 113 A and 113 B)”.', 'gst34'),
  ('CA', 'CA-GST34', '114', 'total', 'Refund claimed', '{"fr":"Remboursement demandé"}'::jsonb, 170, null, '{}'::text[], array['113C']::text[], null, null, true, false, null, 'GST/HST Return Working Copy, lines 114 and 115: “If the result entered on line 113 C is a negative amount, enter the amount of the refund you are claiming on line 114. If the result entered on line 113 C is a positive amount, enter the amount of your payment on line 115.” One figure, two boxes and a sign: this one is line 113 C subtracted and floored at zero, so it carries the credit and nothing else.', 'gst34'),
  ('CA', 'CA-GST34', '115', 'total', 'Payment enclosed', '{"fr":"Paiement ci-joint"}'::jsonb, 180, null, array['113C']::text[], '{}'::text[], null, null, true, false, null, 'GST/HST Return Working Copy, line 115, the other side of the pair described on line 114: line 113 C added and floored at zero, so it carries what is owed and nothing else. Subsection 228(2) of the Excise Tax Act is what makes a positive net tax remittable, and paragraph 228(2)(b) makes it due on the day the return is due.', 'gst34')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('CA-ASPE-BS', 'CA', 'default', 'Balance sheet — ASPE, short form', 'balance_sheet', 'ASPE', date '1970-01-01', null, 'CPA Canada Handbook — Accounting, Part II, Section 1521, Balance sheet, which names the items a balance sheet presents and the order it presents them in, read with Section 1510, Current assets and current liabilities, for the current/non-current split. Section 71 of the Canada Business Corporations Regulations, 2001 requires annual financial statements to be prepared in accordance with Canadian GAAP, and section 70 of the same regulations defines Canadian GAAP as “generally accepted accounting principles as set out in the CPA Canada Handbook – Accounting”. Canada prescribes no chart of accounts and no statutory line-by-line scheme: this is the short-form presentation ASPE asks for, and the line names are the Handbook''s own words.', 'aspe'),
  ('CA-ASPE-IS', 'CA', 'default', 'Income statement — ASPE, short form', 'income_statement', 'ASPE', date '1970-01-01', null, 'CPA Canada Handbook — Accounting, Part II, Section 1520, Income statement, which lists the items presented separately in an income statement, read with Section 1400, General standards of financial statement presentation. Section 71 of the Canada Business Corporations Regulations, 2001 is what makes the Handbook the standard. Canada prescribes no statutory income statement format, so the grouping here is the short-form one ASPE asks for and no more.', 'aspe')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_line_templates
  (statement_code, code, parent_code, name, name_i18n, sequence, sign, is_total,
   plus_lines, minus_lines, xbrl_element, legal_reference, source_key)
values
  ('CA-ASPE-BS', '10', null, 'Cash and cash equivalents', '{"fr":"Encaisse et équivalents de trésorerie"}'::jsonb, 10, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '20', null, 'Accounts receivable', '{"fr":"Comptes clients"}'::jsonb, 20, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '30', null, 'Inventory', '{"fr":"Stocks"}'::jsonb, 30, 1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3031, Inventories, which requires the carrying amount of inventories to be presented; Section 1510 puts it among the current assets.', 'aspe'),
  ('CA-ASPE-BS', '40', null, 'Prepaid expenses', '{"fr":"Frais payés d''avance"}'::jsonb, 40, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '50', null, 'Recoverable sales taxes', '{"fr":"Taxes de vente à recouvrer"}'::jsonb, 50, 1, false, '{}'::text[], '{}'::text[], null, 'Input tax credits under subsection 169(1) of the Excise Tax Act and input tax refunds under section 199 of the Act respecting the Québec sales tax are amounts receivable from two administrations, so they sit among the current assets and not as a deduction from the taxes charged. The account the return is settled to, 1340, is on this line too: a period that ends in a credit is a claim on the Receiver General.', 'aspe'),
  ('CA-ASPE-BS', '60', null, 'Other current assets', '{"fr":"Autres actifs à court terme"}'::jsonb, 60, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '100', null, 'Total current assets', '{"fr":"Total de l''actif à court terme"}'::jsonb, 70, 1, true, array['10', '20', '30', '40', '50', '60']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '110', null, 'Capital assets, at cost', '{"fr":"Immobilisations, au coût"}'::jsonb, 80, 1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3061, Property, plant and equipment, which requires the cost, the accumulated amortization and the amortization of the period to be disclosed for each major category.', 'aspe'),
  ('CA-ASPE-BS', '120', null, 'Accumulated amortization', '{"fr":"Amortissement cumulé"}'::jsonb, 90, 1, false, '{}'::text[], '{}'::text[], null, 'Section 3061 again: the accumulated amortization is presented, and it carries a credit balance, so this line reads negative and is added to the line above rather than subtracted from it.', 'aspe'),
  ('CA-ASPE-BS', '130', null, 'Intangible and other long-term assets', '{"fr":"Immobilisations incorporelles et autres actifs à long terme"}'::jsonb, 100, 1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3064, Goodwill and intangible assets.', 'aspe'),
  ('CA-ASPE-BS', '140', null, 'Total capital and other assets', '{"fr":"Total des immobilisations et des autres actifs"}'::jsonb, 110, 1, true, array['110', '120', '130']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '200', null, 'TOTAL ASSETS', '{"fr":"TOTAL DE L''ACTIF"}'::jsonb, 120, 1, true, array['100', '140']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '300', null, 'Accounts payable and accrued liabilities', '{"fr":"Comptes fournisseurs et charges à payer"}'::jsonb, 130, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '310', null, 'Sales taxes payable', '{"fr":"Taxes de vente à payer"}'::jsonb, 140, -1, false, '{}'::text[], '{}'::text[], null, 'The tax a registrant collects is held for the administration that levies it — the Receiver General under subsection 228(2) of the Excise Tax Act, Revenu Québec, or a province under its own sales tax statute — so it is a liability of the company and never its revenue. The four administrations keep separate accounts here and one line presents them.', 'aspe'),
  ('CA-ASPE-BS', '320', null, 'Other current liabilities', '{"fr":"Autres passifs à court terme"}'::jsonb, 150, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '330', null, 'Current portion of long-term debt', '{"fr":"Tranche à court terme de la dette à long terme"}'::jsonb, 160, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '400', null, 'Total current liabilities', '{"fr":"Total du passif à court terme"}'::jsonb, 170, 1, true, array['300', '310', '320', '330']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '410', null, 'Long-term liabilities', '{"fr":"Passif à long terme"}'::jsonb, 180, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '500', null, 'Total liabilities', '{"fr":"Total du passif"}'::jsonb, 190, 1, true, array['400', '410']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '600', null, 'Share capital', '{"fr":"Capital-actions"}'::jsonb, 200, -1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3251, Equity, which requires share capital, contributed surplus and retained earnings to be presented separately.', 'aspe'),
  ('CA-ASPE-BS', '610', null, 'Contributed surplus and accumulated other comprehensive income', '{"fr":"Surplus d''apport et cumul des autres éléments du résultat étendu"}'::jsonb, 210, -1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '620', null, 'Dividends declared', '{"fr":"Dividendes déclarés"}'::jsonb, 220, -1, false, '{}'::text[], '{}'::text[], null, 'Section 3251 again: a dividend declared is a charge against retained earnings and is presented separately. The account carries a debit balance, so the line reads negative.', 'aspe'),
  ('CA-ASPE-BS', '630', null, 'Retained earnings', '{"fr":"Bénéfices non répartis"}'::jsonb, 230, -1, false, '{}'::text[], '{}'::text[], null, 'Section 3251, and Section 1521 for its place on the balance sheet. The result of the open year is not here until close_fiscal_year() puts it there: until then the assets of this statement exceed the liabilities and the equity by exactly the net income of the income statement.', 'aspe'),
  ('CA-ASPE-BS', '700', null, 'Total shareholders'' equity', '{"fr":"Total des capitaux propres"}'::jsonb, 240, 1, true, array['600', '610', '620', '630']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-BS', '800', null, 'TOTAL LIABILITIES AND SHAREHOLDERS'' EQUITY', '{"fr":"TOTAL DU PASSIF ET DES CAPITAUX PROPRES"}'::jsonb, 250, 1, true, array['500', '700']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-IS', '10', null, 'Revenue', '{"fr":"Produits"}'::jsonb, 10, -1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3400, Revenue, and Section 1520, which requires revenue to be presented as a separate item of the income statement.', 'aspe'),
  ('CA-ASPE-IS', '20', null, 'Cost of goods sold', '{"fr":"Coût des marchandises vendues"}'::jsonb, 20, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-IS', '30', null, 'Gross profit', '{"fr":"Bénéfice brut"}'::jsonb, 30, 1, true, array['10']::text[], array['20']::text[], null, null, null),
  ('CA-ASPE-IS', '40', null, 'Salaries, wages and employee benefits', '{"fr":"Salaires et avantages sociaux"}'::jsonb, 40, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-IS', '50', null, 'Operating expenses', '{"fr":"Charges d''exploitation"}'::jsonb, 50, 1, false, '{}'::text[], '{}'::text[], null, 'Section 1520 lists amortization of property, plant and equipment and of intangible assets among the items presented separately; this pack keeps them in accounts 6800 and 6810 so a reader of the chart finds them, and presents them inside operating expenses, which is what a short-form statement does.', 'aspe'),
  ('CA-ASPE-IS', '60', null, 'Total operating expenses', '{"fr":"Total des charges d''exploitation"}'::jsonb, 60, 1, true, array['40', '50']::text[], '{}'::text[], null, null, null),
  ('CA-ASPE-IS', '70', null, 'Income from operations', '{"fr":"Bénéfice d''exploitation"}'::jsonb, 70, 1, true, array['30']::text[], array['60']::text[], null, null, null),
  ('CA-ASPE-IS', '80', null, 'Other income', '{"fr":"Autres produits"}'::jsonb, 80, -1, false, '{}'::text[], '{}'::text[], null, 'Section 1520 requires investment income and gains from the disposal of property, plant and equipment to be presented separately from revenue; this line is where the pack''s chart keeps them, with the foreign exchange gain of Section 1651.', 'aspe'),
  ('CA-ASPE-IS', '90', null, 'Other expenses', '{"fr":"Autres charges"}'::jsonb, 90, 1, false, '{}'::text[], '{}'::text[], null, 'Section 1520 for interest on long-term debt and for losses from the disposal of property, plant and equipment, and Section 1651, Foreign currency translation, for the exchange loss.', 'aspe'),
  ('CA-ASPE-IS', '100', null, 'Income before income taxes', '{"fr":"Bénéfice avant impôts"}'::jsonb, 100, 1, true, array['70', '80']::text[], array['90']::text[], null, null, null),
  ('CA-ASPE-IS', '110', null, 'Income taxes', '{"fr":"Impôts sur le revenu"}'::jsonb, 110, 1, false, '{}'::text[], '{}'::text[], null, 'CPA Canada Handbook — Accounting, Part II, Section 3465, Income taxes, and Section 1520, which requires income taxes to be presented separately.', 'aspe'),
  ('CA-ASPE-IS', '120', null, 'Net income', '{"fr":"Bénéfice net"}'::jsonb, 120, 1, true, array['100']::text[], array['110']::text[], null, null, null)
on conflict (statement_code, code) do update set
  parent_code     = excluded.parent_code,
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  sign            = excluded.sign,
  is_total        = excluded.is_total,
  plus_lines      = excluded.plus_lines,
  minus_lines     = excluded.minus_lines,
  xbrl_element    = excluded.xbrl_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

