update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'No statute of Canada requires the invoice of a business to carry a number, and neither does any province. What the law asks of a document is set out in section 3 of the Input Tax Credit Information (GST/HST) Regulations, and it is a list of facts and not a sequence: under $100 the supplier''s name, the date and the total; from $100 the supplier''s registration number and the tax; from $500 the recipient''s name, the terms of payment and a description of each supply. Section 2 of the same regulations makes any of an invoice, a receipt, a credit-card slip, a debit note, a book of account, a written contract or “any record contained in a computerized or electronic retrieval or data storage system” supporting documentation. `free` is therefore Canada''s answer and not a gap in this pack, and `{CODE}-{NNNN}` is a convention it proposes rather than a form anybody prescribes.',
  numbering_source_key          = 'itc-regs',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'Excise Tax Act, subsection 168(1): tax is payable on the earlier of the day the consideration is paid and the day it becomes due. Subsection 152(1) is what makes the invoice the usual answer to the second half — consideration becomes due on the earliest of the day the supplier first issues an invoice for it, the date of that invoice, the day the supplier would have issued it but for an undue delay, and the day the recipient is required to pay under a written agreement. The supply is the backstop and not the principle: subsection 168(3) reaches only the case where the consideration has neither been paid nor become due by the last day of the month following the month the property was delivered. So the invoice fixes the tax point of an invoiced supply, which is what `invoice_date` says, and the payment branch of 168(1) bites only on a prepayment — a document Ekwo has no concept of, which docs/international.md already records as a limit of the core.',
  tax_point_source_key          = 'eta',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Excise Tax Act, section 286 requires every person carrying on a business to keep records in such form and containing such information as will enable the determination of their liabilities and obligations, and to keep them for six years after the end of the year they relate to; subsection 286(3) lets the Minister require a person who has not kept adequate records to keep the ones the Minister specifies. A record that could be taken back after the fact is not one of those, so a posted document of a Canadian company is undone by a credit note that names it and in no other way.',
  posted_edit_policy_source_key = 'eta',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No statute of Canada, federal or provincial, obliges businesses to exchange electronic invoices between themselves, and no date has been set for one. There is therefore no national profile to declare. What the law says about the medium it says in section 2 of the Input Tax Credit Information (GST/HST) Regulations, and it says it the other way round: supporting documentation for an input tax credit already includes “any record contained in a computerized or electronic retrieval or data storage system”, so an electronic invoice has been good enough for thirty-five years and has never been compulsory. What is compulsory is the *return*: for reporting periods beginning on or after 1 January 2024 every GST/HST registrant other than a charity or a selected listed financial institution has to file electronically, and Revenu Québec requires the same of form FPZ-500 from the same date. Filing a return online is not issuing an electronic invoice, and the two are not run together here. A supplier to the federal government invoices through the CanadaBuys procurement system, which is procurement policy and reaches nobody else. `party_scheme` and `vat_scheme` are empty: nothing prescribes which of a Canadian party''s several registration identifiers — the business number, the GST/HST account, the QST number — it would be addressed by on a network no statute names.',
  einvoice_source_key           = 'itc-regs',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['bai2', 'ofx', 'csv', 'camt.053']::text[],
  payment_formats               = array['eft', 'csv']::text[],
  fiscal_year_default           = 'calendar'
 where country = 'CA';
